import 'package:plug_agente/infrastructure/external_services/sql_anywhere_constraint_sql.dart';

/// Fixed catalog SQL, never caller SQL. All resource names are bound values.
abstract final class SourceSchemaSql {
  static String query(String dialect, String kind) => switch ((dialect, kind)) {
    ('postgres', 'tables') =>
      "SELECT table_schema AS table_schem,table_name,CASE WHEN table_type='VIEW' THEN 'view' ELSE 'table' END AS table_type FROM information_schema.tables WHERE table_schema=:schema AND table_name=:table",
    ('postgres', 'columns') =>
      "SELECT table_schema AS table_schem,table_name,column_name,udt_name AS type_name,ordinal_position,CASE WHEN is_nullable='YES' THEN 1 ELSE 0 END AS nullable,COALESCE(character_maximum_length,numeric_precision) AS column_size,numeric_scale AS decimal_digits FROM information_schema.columns WHERE table_schema=:schema AND table_name=:table ORDER BY ordinal_position",
    ('postgres', 'primary') =>
      "SELECT ns.nspname AS table_schem,t.relname AS table_name,a.attname AS column_name,k.idx AS key_seq,c.conname AS pk_name,CASE WHEN NOT i.indisvalid OR NOT i.indisready OR NOT COALESCE((to_jsonb(c)->>'conenforced')::boolean,true) THEN 'disabled' WHEN NOT c.convalidated THEN 'unvalidated' ELSE 'enabled' END AS constraint_status FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace ns ON ns.oid=t.relnamespace JOIN pg_index i ON i.indexrelid=c.conindid CROSS JOIN LATERAL generate_subscripts(c.conkey,1) k(idx) JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=c.conkey[k.idx] WHERE c.contype='p' AND ns.nspname=:schema AND t.relname=:table ORDER BY c.conname,k.idx",
    ('postgres', 'foreign') =>
      "SELECT ns.nspname AS fktable_schem,t.relname AS fktable_name,a.attname AS fkcolumn_name,pns.nspname AS pktable_schem,p.relname AS pktable_name,pa.attname AS pkcolumn_name,k.idx AS key_seq,c.conname AS fk_name,CASE WHEN NOT ri.indisvalid OR NOT ri.indisready OR NOT COALESCE((to_jsonb(c)->>'conenforced')::boolean,true) OR current_setting('session_replication_role')<>'origin' OR EXISTS(SELECT 1 FROM pg_trigger tr WHERE tr.tgconstraint=c.oid AND tr.tgenabled NOT IN ('O','A')) THEN 'disabled' WHEN NOT c.convalidated THEN 'unvalidated' ELSE 'enabled' END AS constraint_status FROM pg_constraint c JOIN pg_index ri ON ri.indexrelid=c.conindid JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace ns ON ns.oid=t.relnamespace JOIN pg_class p ON p.oid=c.confrelid JOIN pg_namespace pns ON pns.oid=p.relnamespace CROSS JOIN LATERAL generate_subscripts(c.conkey,1) k(idx) JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=c.conkey[k.idx] JOIN pg_attribute pa ON pa.attrelid=p.oid AND pa.attnum=c.confkey[k.idx] WHERE c.contype='f' AND ns.nspname=:schema AND t.relname=:table ORDER BY c.conname,k.idx",
    ('mssql', 'tables') =>
      "SELECT s.name AS table_schem,t.name AS table_name,CASE WHEN t.type='V' THEN 'view' ELSE 'table' END AS table_type FROM sys.objects t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE t.type IN ('U','V') AND s.name=:schema AND t.name=:table",
    ('mssql', 'columns') =>
      "SELECT s.name AS table_schem,t.name AS table_name,c.name AS column_name,ty.name AS type_name,c.column_id AS ordinal_position,CAST(c.is_nullable AS INT) AS nullable,CASE WHEN c.max_length=-1 AND ty.name='nvarchar' THEN c.max_length WHEN ty.name IN ('char','varchar','binary','varbinary') THEN c.max_length WHEN ty.name IN ('nchar','nvarchar') THEN c.max_length/2 ELSE c.precision END AS column_size,c.scale AS decimal_digits FROM sys.objects t JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id WHERE t.type IN ('U','V') AND s.name=:schema AND t.name=:table ORDER BY c.column_id",
    ('mssql', 'primary') =>
      "SELECT s.name AS table_schem,t.name AS table_name,c.name AS column_name,i.key_ordinal AS key_seq,k.name AS pk_name,CASE WHEN ix.is_disabled=1 THEN 'disabled' ELSE 'enabled' END AS constraint_status FROM sys.key_constraints k JOIN sys.objects t ON t.object_id=k.parent_object_id JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.indexes ix ON ix.object_id=t.object_id AND ix.index_id=k.unique_index_id JOIN sys.index_columns i ON i.object_id=t.object_id AND i.index_id=k.unique_index_id JOIN sys.columns c ON c.object_id=t.object_id AND c.column_id=i.column_id WHERE k.type='PK' AND i.key_ordinal>0 AND s.name=:schema AND t.name=:table ORDER BY i.key_ordinal",
    ('mssql', 'foreign') =>
      "SELECT s.name AS fktable_schem,t.name AS fktable_name,c.name AS fkcolumn_name,ps.name AS pktable_schem,p.name AS pktable_name,pc.name AS pkcolumn_name,f.constraint_column_id AS key_seq,k.name AS fk_name,CASE WHEN k.is_disabled=1 OR ri.is_disabled=1 THEN 'disabled' WHEN k.is_not_trusted=1 THEN 'unvalidated' ELSE 'enabled' END AS constraint_status FROM sys.foreign_keys k JOIN sys.indexes ri ON ri.object_id=k.referenced_object_id AND ri.index_id=k.key_index_id JOIN sys.foreign_key_columns f ON f.constraint_object_id=k.object_id JOIN sys.objects t ON t.object_id=f.parent_object_id JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.columns c ON c.object_id=t.object_id AND c.column_id=f.parent_column_id JOIN sys.objects p ON p.object_id=f.referenced_object_id JOIN sys.schemas ps ON ps.schema_id=p.schema_id JOIN sys.columns pc ON pc.object_id=p.object_id AND pc.column_id=f.referenced_column_id WHERE s.name=:schema AND t.name=:table ORDER BY k.name,f.constraint_column_id",
    ('sybase', 'tables') =>
      "SELECT u.user_name AS table_schem,t.table_name,CASE WHEN t.table_type_str='VIEW' THEN 'view' ELSE 'table' END AS table_type FROM SYS.SYSTAB t JOIN SYS.SYSUSER u ON u.user_id=t.creator WHERE t.table_type_str IN ('BASE','VIEW') AND u.user_name=:schema AND t.table_name=:table",
    ('sybase', 'columns') =>
      "SELECT u.user_name AS table_schem,t.table_name,c.column_name,d.domain_name AS type_name,c.column_id AS ordinal_position,CASE WHEN c.nulls='Y' THEN 1 ELSE 0 END AS nullable,c.width AS column_size,c.scale AS decimal_digits FROM SYS.SYSTAB t JOIN SYS.SYSUSER u ON u.user_id=t.creator JOIN SYS.SYSTABCOL c ON c.table_id=t.table_id JOIN SYS.SYSDOMAIN d ON d.domain_id=c.domain_id WHERE u.user_name=:schema AND t.table_name=:table ORDER BY c.column_id",
    ('sybase', 'primary') => SqlAnywhereConstraintSql.query('primary'),
    ('sybase', 'foreign') => SqlAnywhereConstraintSql.query('foreign'),
    ('firebird', 'tables') =>
      r"SELECT CAST(NULL AS VARCHAR(128)) AS table_schem,TRIM(r.RDB$RELATION_NAME) AS table_name,CASE WHEN r.RDB$VIEW_BLR IS NULL THEN 'table' ELSE 'view' END AS table_type FROM RDB$RELATIONS r WHERE COALESCE(r.RDB$SYSTEM_FLAG,0)=0 AND r.RDB$RELATION_NAME=:table",
    ('firebird', 'columns') =>
      r"SELECT CAST(NULL AS VARCHAR(128)) AS table_schem,TRIM(r.RDB$RELATION_NAME) AS table_name,TRIM(r.RDB$FIELD_NAME) AS column_name,CASE WHEN f.RDB$FIELD_SUB_TYPE=1 THEN 'numeric' WHEN f.RDB$FIELD_SUB_TYPE=2 THEN 'decimal' WHEN f.RDB$FIELD_TYPE=7 THEN 'smallint' WHEN f.RDB$FIELD_TYPE=8 THEN 'integer' WHEN f.RDB$FIELD_TYPE=16 THEN 'bigint' WHEN f.RDB$FIELD_TYPE=10 THEN 'float' WHEN f.RDB$FIELD_TYPE=27 THEN 'double precision' WHEN f.RDB$FIELD_TYPE=12 THEN 'date' WHEN f.RDB$FIELD_TYPE=13 THEN 'time' WHEN f.RDB$FIELD_TYPE=35 THEN 'timestamp' WHEN f.RDB$FIELD_TYPE=14 THEN 'char' WHEN f.RDB$FIELD_TYPE=37 THEN 'varchar' WHEN f.RDB$FIELD_TYPE=23 THEN 'boolean' WHEN f.RDB$FIELD_TYPE=261 THEN 'blob' ELSE 'unsupported' END AS type_name,r.RDB$FIELD_POSITION+1 AS ordinal_position,CASE WHEN COALESCE(r.RDB$NULL_FLAG,f.RDB$NULL_FLAG,0)=1 THEN 0 ELSE 1 END AS nullable,COALESCE(f.RDB$CHARACTER_LENGTH,f.RDB$FIELD_PRECISION,f.RDB$FIELD_LENGTH) AS column_size,-f.RDB$FIELD_SCALE AS decimal_digits FROM RDB$RELATION_FIELDS r JOIN RDB$FIELDS f ON f.RDB$FIELD_NAME=r.RDB$FIELD_SOURCE WHERE r.RDB$RELATION_NAME=:table ORDER BY r.RDB$FIELD_POSITION",
    ('firebird', 'primary') =>
      r"SELECT CAST(NULL AS VARCHAR(128)) AS table_schem,TRIM(c.RDB$RELATION_NAME) AS table_name,TRIM(i.RDB$FIELD_NAME) AS column_name,i.RDB$FIELD_POSITION+1 AS key_seq,TRIM(c.RDB$CONSTRAINT_NAME) AS pk_name,CASE WHEN ix.RDB$INDEX_INACTIVE=0 THEN 'enabled' WHEN ix.RDB$INDEX_INACTIVE=1 THEN 'disabled' ELSE 'unknown' END AS constraint_status FROM RDB$RELATION_CONSTRAINTS c JOIN RDB$INDICES ix ON ix.RDB$INDEX_NAME=c.RDB$INDEX_NAME JOIN RDB$INDEX_SEGMENTS i ON i.RDB$INDEX_NAME=c.RDB$INDEX_NAME WHERE c.RDB$CONSTRAINT_TYPE='PRIMARY KEY' AND c.RDB$RELATION_NAME=:table ORDER BY i.RDB$FIELD_POSITION",
    ('firebird', 'foreign') =>
      r"SELECT CAST(NULL AS VARCHAR(128)) AS fktable_schem,TRIM(c.RDB$RELATION_NAME) AS fktable_name,TRIM(i.RDB$FIELD_NAME) AS fkcolumn_name,CAST(NULL AS VARCHAR(128)) AS pktable_schem,TRIM(p.RDB$RELATION_NAME) AS pktable_name,TRIM(pi.RDB$FIELD_NAME) AS pkcolumn_name,i.RDB$FIELD_POSITION+1 AS key_seq,TRIM(c.RDB$CONSTRAINT_NAME) AS fk_name,CASE WHEN ix.RDB$INDEX_INACTIVE=0 AND px.RDB$INDEX_INACTIVE=0 THEN 'enabled' WHEN ix.RDB$INDEX_INACTIVE=1 OR px.RDB$INDEX_INACTIVE=1 THEN 'disabled' ELSE 'unknown' END AS constraint_status FROM RDB$RELATION_CONSTRAINTS c JOIN RDB$REF_CONSTRAINTS r ON r.RDB$CONSTRAINT_NAME=c.RDB$CONSTRAINT_NAME JOIN RDB$RELATION_CONSTRAINTS p ON p.RDB$CONSTRAINT_NAME=r.RDB$CONST_NAME_UQ JOIN RDB$INDICES ix ON ix.RDB$INDEX_NAME=c.RDB$INDEX_NAME JOIN RDB$INDICES px ON px.RDB$INDEX_NAME=p.RDB$INDEX_NAME JOIN RDB$INDEX_SEGMENTS i ON i.RDB$INDEX_NAME=c.RDB$INDEX_NAME JOIN RDB$INDEX_SEGMENTS pi ON pi.RDB$INDEX_NAME=p.RDB$INDEX_NAME AND pi.RDB$FIELD_POSITION=i.RDB$FIELD_POSITION WHERE c.RDB$CONSTRAINT_TYPE='FOREIGN KEY' AND c.RDB$RELATION_NAME=:table ORDER BY c.RDB$CONSTRAINT_NAME,i.RDB$FIELD_POSITION",
    ('postgres', 'unique') =>
      "SELECT ns.nspname AS table_schem,t.relname AS table_name,a.attname AS column_name,k.idx AS key_seq,ix.relname AS pk_name,CASE WHEN i.indisvalid AND i.indisready THEN 'enabled' ELSE 'disabled' END AS constraint_status FROM pg_index i JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace ns ON ns.oid=t.relnamespace JOIN pg_class ix ON ix.oid=i.indexrelid CROSS JOIN LATERAL generate_series(1,i.indnkeyatts) k(idx) JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=i.indkey[k.idx-1] WHERE i.indisunique AND NOT i.indisprimary AND i.indpred IS NULL AND i.indexprs IS NULL AND ns.nspname=:schema AND t.relname=:table ORDER BY ix.relname,k.idx",
    ('mssql', 'unique') =>
      "SELECT s.name AS table_schem,t.name AS table_name,c.name AS column_name,ic.key_ordinal AS key_seq,i.name AS pk_name,CASE WHEN i.is_disabled=1 THEN 'disabled' ELSE 'enabled' END AS constraint_status FROM sys.indexes i JOIN sys.objects t ON t.object_id=i.object_id JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN sys.columns c ON c.object_id=t.object_id AND c.column_id=ic.column_id WHERE i.is_unique=1 AND i.is_primary_key=0 AND i.has_filter=0 AND i.is_hypothetical=0 AND ic.key_ordinal>0 AND s.name=:schema AND t.name=:table ORDER BY i.name,ic.key_ordinal",
    ('sybase', 'unique') => SqlAnywhereConstraintSql.query('unique'),
    ('firebird', 'unique') =>
      r"SELECT CAST(NULL AS VARCHAR(128)) AS table_schem,TRIM(ix.RDB$RELATION_NAME) AS table_name,TRIM(i.RDB$FIELD_NAME) AS column_name,i.RDB$FIELD_POSITION+1 AS key_seq,TRIM(ix.RDB$INDEX_NAME) AS pk_name,CASE WHEN ix.RDB$INDEX_INACTIVE=0 THEN 'enabled' WHEN ix.RDB$INDEX_INACTIVE=1 THEN 'disabled' ELSE 'unknown' END AS constraint_status FROM RDB$INDICES ix JOIN RDB$INDEX_SEGMENTS i ON i.RDB$INDEX_NAME=ix.RDB$INDEX_NAME WHERE ix.RDB$UNIQUE_FLAG=1 AND ix.RDB$EXPRESSION_BLR IS NULL AND ix.RDB$CONDITION_BLR IS NULL AND ix.RDB$RELATION_NAME=:table AND NOT EXISTS(SELECT 1 FROM RDB$RELATION_CONSTRAINTS c WHERE c.RDB$INDEX_NAME=ix.RDB$INDEX_NAME AND c.RDB$CONSTRAINT_TYPE='PRIMARY KEY') ORDER BY ix.RDB$INDEX_NAME,i.RDB$FIELD_POSITION",
    _ => throw ArgumentError('Unsupported metadata dialect or kind'),
  };
}
